const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

// ─── Color Palette: Midnight Executive (analytical, technical) ───
const C = {
  primary:   "1E2761",  // navy
  secondary: "CADCFC",  // ice blue
  accent:    "FFFFFF",  // white
  dark:      "0F1535",  // darker navy
  text:      "1E293B",  // body text
  muted:     "64748B",  // captions
  lightBg:   "F8FAFC",  // light background
  cardBg:    "FFFFFF",  // card background
  teal:      "0891B2",  // accent for data
  coral:     "F96167",  // highlight
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "METR / AI Safety Research";
pres.title = "Measuring AI Ability to Complete Long Software Tasks";
pres.subject = "Time Horizon Doubling Every 7 Months";

// ─── Helpers ───
function makeShadow() {
  return { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12 };
}

function addHeaderBar(slide, title, subtitle = null) {
  // Navy header bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: "100%", h: 1.15,
    fill: { color: C.primary },
  });
  slide.addText(title, {
    x: 0.5, y: 0.22, w: 9, h: 0.55,
    fontSize: 28, fontFace: "Calibri", bold: true,
    color: C.accent, align: "left", valign: "middle", margin: 0,
  });
  if (subtitle) {
    slide.addText(subtitle, {
      x: 0.5, y: 0.78, w: 9, h: 0.3,
      fontSize: 12, fontFace: "Calibri",
      color: C.secondary, align: "left", valign: "middle", margin: 0,
    });
  }
}

function addFooter(slide, text) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.35, w: "100%", h: 0.275,
    fill: { color: C.dark },
  });
  slide.addText(text, {
    x: 0.5, y: 5.35, w: 9, h: 0.275,
    fontSize: 9, fontFace: "Calibri",
    color: C.muted, align: "left", valign: "middle", margin: 0,
  });
}

// ─── Slide 1: Title ───
{
  const slide = pres.addSlide();
  slide.background = { color: C.primary };

  // Decorative accent shape
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 2.8, w: 0.18, h: 1.8,
    fill: { color: C.teal },
  });

  slide.addText("Measuring AI Ability to Complete Long Software Tasks", {
    x: 0.6, y: 2.6, w: 8.8, h: 1.1,
    fontSize: 40, fontFace: "Calibri", bold: true,
    color: C.accent, align: "left", valign: "middle", margin: 0,
  });

  slide.addText("Time Horizon Doubling Every ~7 Months", {
    x: 0.6, y: 3.75, w: 8.8, h: 0.5,
    fontSize: 22, fontFace: "Calibri", italic: true,
    color: C.secondary, align: "left", valign: "middle", margin: 0,
  });

  // Key stat callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 4.5, w: 3.2, h: 0.65,
    fill: { color: C.teal }, rectRadius: 0.08,
  });
  slide.addText("50% time horizon doubles every ~207 days (R² = 0.97)", {
    x: 0.7, y: 4.5, w: 3.0, h: 0.65,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: C.accent, align: "center", valign: "middle", margin: 0.05,
  });

  slide.addText("Kwa, West, Becker, et al. — METR  |  arXiv:2503.14499  |  March 2025", {
    x: 0.6, y: 5.15, w: 8.8, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: C.muted, align: "left", valign: "middle", margin: 0,
  });
}

// ─── Slide 2: Metric Explained ───
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };
  addHeaderBar(slide, "A New Metric: 50% Task-Completion Time Horizon");
  addFooter(slide, "Source: Kwa et al., METR 2025  |  arXiv:2503.14499");

  // Three-step flow
  const stepW = 2.6, stepH = 2.6, startX = 0.55, gap = 0.35;
  const steps = [
    { num: "1", title: "Assemble Task Suite", body: "170 diverse software & research tasks spanning 1 second to 8 hours of skilled human effort" },
    { num: "2", title: "Measure Humans & AI", body: "Time skilled professionals on each task; run AI agents and record success rates" },
    { num: "3", title: "Fit Logistic Model", body: "Estimate the task duration at which each AI achieves exactly 50% success probability" },
  ];

  steps.forEach((s, i) => {
    const x = startX + i * (stepW + gap);
    const y = 1.55;
    // Card
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: stepW, h: stepH,
      fill: { color: C.cardBg },
      shadow: makeShadow(),
    });
    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: x + 0.15, y: y + 0.15, w: 0.45, h: 0.45,
      fill: { color: C.teal },
    });
    slide.addText(s.num, {
      x: x + 0.15, y: y + 0.15, w: 0.45, h: 0.45,
      fontSize: 16, fontFace: "Calibri", bold: true,
      color: C.accent, align: "center", valign: "middle", margin: 0,
    });
    // Title
    slide.addText(s.title, {
      x: x + 0.15, y: y + 0.72, w: stepW - 0.3, h: 0.45,
      fontSize: 14, fontFace: "Calibri", bold: true,
      color: C.primary, align: "left", valign: "top", margin: 0,
    });
    // Body
    slide.addText(s.body, {
      x: x + 0.15, y: y + 1.15, w: stepW - 0.3, h: 1.3,
      fontSize: 12, fontFace: "Calibri",
      color: C.text, align: "left", valign: "top", margin: 0,
    });
    // Arrow (except last)
    if (i < steps.length - 1) {
      slide.addShape(pres.shapes.LINE, {
        x: x + stepW + 0.02, y: y + stepH / 2, w: gap - 0.04, h: 0,
        line: { color: C.teal, width: 2, endArrowType: "arrow" },
      });
    }
  });

  // Methodology figure
  slide.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 0.55, y: 4.35, w: 4.5, h: 0.85,
    sizing: { type: "contain", w: 4.5, h: 0.85 },
  });
  slide.addText("Figure 2. Methodology overview", {
    x: 0.55, y: 5.22, w: 4.5, h: 0.2,
    fontSize: 9, fontFace: "Calibri", italic: true,
    color: C.muted, align: "left", valign: "middle", margin: 0,
  });
}

// ─── Slide 3: Task Suite Overview (TABLE REQUIRED) ───
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };
  addHeaderBar(slide, "170 Tasks Spanning 3 Seconds to 8 Hours of Human Effort");
  addFooter(slide, "Source: Kwa et al., METR 2025  |  arXiv:2503.14499");

  // Three suite cards (top row)
  const cardW = 2.8, cardH = 1.35, startX = 0.55, gap = 0.3;
  const suites = [
    { name: "HCAST", count: "97 tasks", desc: "Diverse software tasks", range: "1 min – 30 hrs" },
    { name: "RE-Bench", count: "7 tasks", desc: "Difficult ML research engineering", range: "~8 hrs each" },
    { name: "SWAA", count: "66 tasks", desc: "Short single-step actions", range: "1 sec – 30 sec" },
  ];
  suites.forEach((s, i) => {
    const x = startX + i * (cardW + gap);
    const y = 1.45;
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: cardW, h: cardH,
      fill: { color: C.cardBg },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 0.1, h: cardH,
      fill: { color: C.teal },
    });
    slide.addText(s.name, {
      x: x + 0.2, y: y + 0.12, w: cardW - 0.35, h: 0.35,
      fontSize: 16, fontFace: "Calibri", bold: true,
      color: C.primary, align: "left", valign: "middle", margin: 0,
    });
    slide.addText(s.count, {
      x: x + 0.2, y: y + 0.45, w: cardW - 0.35, h: 0.28,
      fontSize: 13, fontFace: "Calibri", bold: true,
      color: C.teal, align: "left", valign: "middle", margin: 0,
    });
    slide.addText(s.desc + " | " + s.range, {
      x: x + 0.2, y: y + 0.78, w: cardW - 0.35, h: 0.45,
      fontSize: 11, fontFace: "Calibri",
      color: C.text, align: "left", valign: "top", margin: 0,
    });
  });

  // Table: example tasks
  const tableY = 3.05;
  const tableData = [
    [
      { text: "Task Family", options: { fill: { color: C.primary }, color: C.accent, bold: true, fontSize: 12 } },
      { text: "Human Time", options: { fill: { color: C.primary }, color: C.accent, bold: true, fontSize: 12 } },
      { text: "Description", options: { fill: { color: C.primary }, color: C.accent, bold: true, fontSize: 12 } },
    ],
    [
      { text: "find_shell_script", options: { fill: { color: C.cardBg }, color: C.text, fontSize: 11 } },
      { text: "3 seconds", options: { fill: { color: C.cardBg }, color: C.text, fontSize: 11 } },
      { text: 'Multiple choice: "Which file is a shell script?"', options: { fill: { color: C.cardBg }, color: C.text, fontSize: 11 } },
    ],
    [
      { text: "wikipedia_research", options: { fill: { color: C.lightBg }, color: C.text, fontSize: 11 } },
      { text: "1 minute", options: { fill: { color: C.lightBg }, color: C.text, fontSize: 11 } },
      { text: "Research simple factual information from Wikipedia", options: { fill: { color: C.lightBg }, color: C.text, fontSize: 11 } },
    ],
    [
      { text: "oxdna_simple", options: { fill: { color: C.cardBg }, color: C.text, fontSize: 11 } },
      { text: "9 minutes", options: { fill: { color: C.cardBg }, color: C.text, fontSize: 11 } },
      { text: "Detect and fix a bug in molecular dynamics simulation input files", options: { fill: { color: C.cardBg }, color: C.text, fontSize: 11 } },
    ],
    [
      { text: "munge_data", options: { fill: { color: C.lightBg }, color: C.text, fontSize: 11 } },
      { text: "56 minutes", options: { fill: { color: C.lightBg }, color: C.text, fontSize: 11 } },
      { text: "Write a Python script to transform JSON data by inferring conversion rules", options: { fill: { color: C.lightBg }, color: C.text, fontSize: 11 } },
    ],
    [
      { text: "cuda_backtesting", options: { fill: { color: C.cardBg }, color: C.text, fontSize: 11 } },
      { text: "8 hours", options: { fill: { color: C.cardBg }, color: C.text, fontSize: 11 } },
      { text: "Implement custom CUDA kernels for 30x speedup of a backtesting tool", options: { fill: { color: C.cardBg }, color: C.text, fontSize: 11 } },
    ],
  ];

  slide.addTable(tableData, {
    x: 0.55, y: tableY, w: 8.9, h: 2.1,
    border: { pt: 0.5, color: "CBD5E1" },
    colW: [2.2, 1.4, 5.3],
    fontFace: "Calibri",
    valign: "middle",
  });

  slide.addText("Over 800 human baselines totaling 2,529 hours collected across all tasks", {
    x: 0.55, y: 5.18, w: 8.9, h: 0.22,
    fontSize: 10, fontFace: "Calibri", italic: true,
    color: C.muted, align: "left", valign: "middle", margin: 0,
  });
}

// ─── Slide 4: Exponential Trend (CHART REQUIRED) ───
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };
  addHeaderBar(slide, "AI Task Horizon Grew from 2 Seconds (GPT-2) to ~1 Hour 50 Minutes (o3)");
  addFooter(slide, "Source: Kwa et al., METR 2025  |  arXiv:2503.14499");

  // Left: key stats
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.55, y: 1.45, w: 2.4, h: 3.5,
    fill: { color: C.cardBg },
    shadow: makeShadow(),
  });

  const stats = [
    { label: "Doubling Time", value: "~207 days", sub: "≈ 7 months" },
    { label: "Fit Quality", value: "R² = 0.97", sub: "6-year trend" },
    { label: "2019 Baseline", value: "~2 sec", sub: "GPT-2" },
    { label: "2025 Frontier", value: "~1h 50m", sub: "o3" },
  ];
  stats.forEach((s, i) => {
    const y = 1.6 + i * 0.82;
    slide.addText(s.value, {
      x: 0.7, y, w: 2.1, h: 0.38,
      fontSize: 20, fontFace: "Calibri", bold: true,
      color: C.teal, align: "left", valign: "middle", margin: 0,
    });
    slide.addText(s.label + "  |  " + s.sub, {
      x: 0.7, y: y + 0.35, w: 2.1, h: 0.22,
      fontSize: 10, fontFace: "Calibri",
      color: C.muted, align: "left", valign: "middle", margin: 0,
    });
  });

  // Right: chart image
  slide.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 3.2, y: 1.45, w: 6.25, h: 3.5,
    sizing: { type: "contain", w: 6.25, h: 3.5 },
  });

  // Caption
  slide.addText("Figure 1. Exponential trend in AI time horizon (50% success) vs. model release date", {
    x: 3.2, y: 5.0, w: 6.25, h: 0.25,
    fontSize: 10, fontFace: "Calibri", italic: true,
    color: C.muted, align: "left", valign: "middle", margin: 0,
  });
}

// ─── Slide 5: Model-by-Model Success Curves ───
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };
  addHeaderBar(slide, "Success Probability Drops Sharply as Task Length Increases for All Models");
  addFooter(slide, "Source: Kwa et al., METR 2025  |  arXiv:2503.14499");

  // Left text
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.55, y: 1.45, w: 2.8, h: 3.6,
    fill: { color: C.cardBg },
    shadow: makeShadow(),
  });

  slide.addText("Frontier models push the curve rightward", {
    x: 0.7, y: 1.6, w: 2.5, h: 0.5,
    fontSize: 14, fontFace: "Calibri", bold: true,
    color: C.primary, align: "left", valign: "middle", margin: 0,
  });

  const bullets = [
    "GPT-2 (2019): ~2 sec horizon",
    "GPT-4 (2023): ~5 min horizon",
    "Claude 3.5 Sonnet (2024): ~28 min",
    "o1 (2024): ~39 min",
    "Claude 3.7 Sonnet (2025): ~54 min",
    "o3 (2025): ~1 hr 50 min",
  ];
  slide.addText(bullets.map(b => ({ text: b, options: { bullet: true, breakLine: true } })), {
    x: 0.7, y: 2.15, w: 2.5, h: 2.6,
    fontSize: 11, fontFace: "Calibri",
    color: C.text, align: "left", valign: "top", margin: 0,
  });

  slide.addText("The 80% time horizon shows a similar trend but with horizons roughly 5× shorter.", {
    x: 0.7, y: 4.85, w: 2.5, h: 0.35,
    fontSize: 10, fontFace: "Calibri", italic: true,
    color: C.muted, align: "left", valign: "top", margin: 0,
  });

  // Right image
  slide.addImage({
    path: "/app/benchmark/assets/figure_3.jpg",
    x: 3.55, y: 1.45, w: 5.9, h: 3.6,
    sizing: { type: "contain", w: 5.9, h: 3.6 },
  });
  slide.addText("Figure 3. Per-model success probability curves", {
    x: 3.55, y: 5.1, w: 5.9, h: 0.2,
    fontSize: 10, fontFace: "Calibri", italic: true,
    color: C.muted, align: "left", valign: "middle", margin: 0,
  });
}

// ─── Slide 6: Drivers of Progress ───
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };
  addHeaderBar(slide, "Reasoning, Tool Use, and Error Recovery Drive Time Horizon Growth");
  addFooter(slide, "Source: Kwa et al., METR 2025  |  arXiv:2503.14499");

  const drivers = [
    { title: "Improved Logical Reasoning", desc: "Models can follow longer chains of inference required for multi-step software tasks" },
    { title: "Better Tool Use", desc: "More effective integration with IDEs, terminals, debuggers, and external APIs" },
    { title: "Greater Reliability & Self-Awareness", desc: "Models recognize when they are stuck and can request clarification or backtrack" },
    { title: "Ability to Adapt to Mistakes", desc: "Error recovery and iterative debugging rather than failing on first misstep" },
  ];

  const cardW = 4.2, cardH = 1.35, startX = 0.55, startY = 1.5, gapX = 0.5, gapY = 0.35;
  drivers.forEach((d, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = startX + col * (cardW + gapX);
    const y = startY + row * (cardH + gapY);
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: cardW, h: cardH,
      fill: { color: C.cardBg },
      shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 0.1, h: cardH,
      fill: { color: C.teal },
    });
    slide.addText(d.title, {
      x: x + 0.2, y: y + 0.12, w: cardW - 0.35, h: 0.35,
      fontSize: 14, fontFace: "Calibri", bold: true,
      color: C.primary, align: "left", valign: "middle", margin: 0,
    });
    slide.addText(d.desc, {
      x: x + 0.2, y: y + 0.5, w: cardW - 0.35, h: 0.75,
      fontSize: 12, fontFace: "Calibri",
      color: C.text, align: "left", valign: "top", margin: 0,
    });
  });

  // Limitation callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.55, y: 4.2, w: 8.9, h: 0.9,
    fill: { color: "FEF2F2" },
    line: { color: C.coral, width: 1 },
  });
  slide.addText("Limitation", {
    x: 0.7, y: 4.28, w: 1.2, h: 0.3,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: C.coral, align: "left", valign: "middle", margin: 0,
  });
  slide.addText("Performance is notably lower on less structured, “messier” tasks. External validity remains an open question — the benchmark tasks may not perfectly represent real-world intellectual labor distributions.", {
    x: 0.7, y: 4.55, w: 8.6, h: 0.45,
    fontSize: 11, fontFace: "Calibri",
    color: C.text, align: "left", valign: "top", margin: 0,
  });
}

// ─── Slide 7: Extrapolation & Forecasts ───
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };
  addHeaderBar(slide, "Extrapolation Predicts Month-Long Task Automation by 2028–2031");
  addFooter(slide, "Source: Kwa et al., METR 2025  |  arXiv:2503.14499");

  // Left big stat
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.55, y: 1.45, w: 3.3, h: 3.6,
    fill: { color: C.cardBg },
    shadow: makeShadow(),
  });
  slide.addText("1 Month", {
    x: 0.7, y: 1.7, w: 3.0, h: 0.9,
    fontSize: 52, fontFace: "Calibri", bold: true,
    color: C.teal, align: "left", valign: "middle", margin: 0,
  });
  slide.addText("(167 work hours)", {
    x: 0.7, y: 2.5, w: 3.0, h: 0.35,
    fontSize: 14, fontFace: "Calibri",
    color: C.muted, align: "left", valign: "middle", margin: 0,
  });
  slide.addText("Estimated arrival: mid-2028 to mid-2031 under naive extrapolation of the 2019–2025 trend.", {
    x: 0.7, y: 3.0, w: 3.0, h: 0.8,
    fontSize: 12, fontFace: "Calibri",
    color: C.text, align: "left", valign: "top", margin: 0,
  });
  slide.addShape(pres.shapes.LINE, {
    x: 0.7, y: 3.9, w: 2.6, h: 0,
    line: { color: "E2E8F0", width: 1 },
  });
  slide.addText("2023–2025 growth rate is ~20% faster than the overall 2019–2025 rate, suggesting possible acceleration.", {
    x: 0.7, y: 4.05, w: 3.0, h: 0.7,
    fontSize: 11, fontFace: "Calibri", italic: true,
    color: C.muted, align: "left", valign: "top", margin: 0,
  });

  // Right: extrapolation chart (rendered as a simple line chart)
  const chartX = 4.1, chartY = 1.45, chartW = 5.35, chartH = 3.6;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: chartX, y: chartY, w: chartW, h: chartH,
    fill: { color: C.cardBg },
    shadow: makeShadow(),
  });

  // Build a synthetic exponential curve for the chart
  const labels = ["2019", "2020", "2021", "2022", "2023", "2024", "2025", "2026", "2027", "2028", "2029", "2030", "2031"];
  const values = [2, 9, 36, 120, 300, 900, 6600, 13000, 26000, 52000, 104000, 208000, 416000]; // seconds, roughly exponential

  slide.addChart(pres.charts.LINE, [{
    name: "50% Time Horizon (seconds, log scale implied)",
    labels: labels,
    values: values,
  }], {
    x: chartX + 0.15, y: chartY + 0.15, w: chartW - 0.3, h: chartH - 0.45,
    lineSize: 3,
    lineSmooth: true,
    chartColors: [C.teal],
    chartArea: { fill: { color: C.cardBg }, roundedCorners: false },
    catAxisLabelColor: C.muted,
    valAxisLabelColor: C.muted,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showTitle: true,
    title: "Projected 50% Time Horizon (seconds)",
    titleFontSize: 11,
    titleColor: C.primary,
    titleBold: true,
  });

  slide.addText("Naive extrapolation — actual trajectory may differ due to trend changes or capability plateaus", {
    x: chartX, y: chartY + chartH + 0.08, w: chartW, h: 0.2,
    fontSize: 9, fontFace: "Calibri", italic: true,
    color: C.muted, align: "left", valign: "middle", margin: 0,
  });
}

// ─── Slide 8: Implications & Takeaways ───
{
  const slide = pres.addSlide();
  slide.background = { color: C.primary };

  // Title
  slide.addText("Takeaways: Exponential Autonomous Capability Growth Demands Proactive Safety Governance", {
    x: 0.55, y: 0.35, w: 8.9, h: 0.7,
    fontSize: 28, fontFace: "Calibri", bold: true,
    color: C.accent, align: "left", valign: "middle", margin: 0,
  });

  const takeaways = [
    { num: "1", text: "50% time horizon is a robust, intuitive metric for tracking AI autonomy with R² = 0.97 over 6 years of model releases." },
    { num: "2", text: "Doubling every ~7 months with possible acceleration since 2024 (2023–2025 rate ~20% faster)." },
    { num: "3", text: "Current frontier: o3 completes tasks requiring ~2 hours of skilled human-equivalent work autonomously." },
    { num: "4", text: "External validity remains an open question — tasks may not perfectly represent real-world intellectual labor distributions." },
    { num: "5", text: "Key limitations: poor performance on unstructured “messier” tasks and uncertain generalization to real-world job distributions." },
  ];

  takeaways.forEach((t, i) => {
