import sys, xml.etree.ElementTree as ET
root = ET.fromstring(sys.stdin.read())
ns = {'a': 'http://schemas.openxmlformats.org/drawingml/2006/main', 'p': 'http://schemas.openxmlformats.org/presentationml/2006/main'}
# Find all table cells
tbl = root.find('.//a:tbl', ns)
rows = tbl.findall('a:tr', ns)
for i, row in enumerate(rows[:3]):  # First 3 rows
    cells = row.findall('a:tc', ns)
    for j, cell in enumerate(cells[:2]):  # First 2 cells per row
        txBody = cell.find('a:txBody', ns)
        if txBody is not None:
            for p in txBody.findall('a:p', ns):
                for r in p.findall('a:r', ns):
                    rPr = r.find('a:rPr', ns)
                    t = r.find('a:t', ns)
                    if rPr is not None and t is not None:
                        fill = rPr.find('a:solidFill/a:srgbClr', ns)
                        if fill is not None:
                            print(f'Row {i}, Cell {j}: text=\"{t.text[:30]}...\", color={fill.get(\"val\")}')
